  Dashboard, People, Warning, ExitToApp, 
  Visibility, Delete, CheckCircle 
} from '@mui/icons-material';
import { useNavigate } from 'react-router-dom';
import NivraLogo from '../components/NivraLogo.jsx';

const AdminDashboard = () => {
  const [stats, setStats] = useState({
    totalUsers: 0,
    activeAlerts: 0,
    resolvedAlerts: 0,
    onlineUsers: 0
  });
  const [alerts, setAlerts] = useState([]);
  const [users, setUsers] = useState([]);
  const navigate = useNavigate();

  useEffect(() => {
    fetchDashboardData();
  }, []);

  const fetchDashboardData = async () => {
    try {
      const token = localStorage.getItem('adminToken');

      // Fetch stats
      const statsRes = await fetch('http://localhost:5000/api/admin/stats', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      if (statsRes.ok) {
        const statsData = await statsRes.json();
        setStats(statsData);
      }

      // Fetch recent alerts
      const alertsRes = await fetch('http://localhost:5000/api/admin/alerts', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      if (alertsRes.ok) {
        const alertsData = await alertsRes.json();
        setAlerts(alertsData);
      }

      // Fetch users
      const usersRes = await fetch('http://localhost:5000/api/admin/users', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      if (usersRes.ok) {
        const usersData = await usersRes.json();
        setUsers(usersData);
      }
    } catch (error) {
      console.error('Error fetching dashboard data:', error);
    }
  };

  const handleLogout = () => {
    localStorage.removeItem('adminToken');
    localStorage.removeItem('adminUser');
    navigate('/admin/login');
  };

  const resolveAlert = async (alertId) => {
    try {
      const token = localStorage.getItem('adminToken');
      await fetch(`http://localhost:5000/api/admin/alerts/${alertId}/resolve`, {
        method: 'PUT',
        headers: { 'Authorization': `Bearer ${token}` }
      });
      fetchDashboardData();
    } catch (error) {
      console.error('Error resolving alert:', error);
    }
  };

  return (
    <div style={{
      background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
      minHeight: '100vh',
      fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
      maxWidth: '414px',
      margin: '0 auto',
      position: 'relative'
    }}>
      {/* Status Bar */}
      <div style={{
        background: 'rgba(0,0,0,0.9)',
        padding: '8px 20px 5px 20px',
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'center',
        fontSize: '14px',
        fontWeight: '600',
        color: 'white'
      }}>
        <div>9:41</div>
        <div style={{ display: 'flex', alignItems: 'center', gap: '5px' }}>
          <span style={{ color: '#34c759', fontSize: '12px' }}>● Admin</span>
          <span>📶</span>
        </div>
      </div>

      {/* Header */}
      <div style={{
        background: 'rgba(255,255,255,0.95)',
        backdropFilter: 'blur(20px)',
        padding: '20px',
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'center',
        borderBottom: '1px solid #f0f0f0',
        position: 'sticky',
        top: '0',
        zIndex: '1000'
      }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
          <NivraLogo size={40} />
          <div>
            <h1 style={{ margin: '0', color: '#8A2BE2', fontSize: '24px', fontWeight: '700' }}>ADMIN</h1>
            <p style={{ margin: '2px 0 0 0', color: '#666', fontSize: '12px' }}>Control Panel</p>
          </div>
        </div>
        <button 
          onClick={handleLogout}
          style={{
            background: '#ff3b30',
            color: 'white',
            border: 'none',
            borderRadius: '20px',
            padding: '8px 16px',
            fontSize: '14px',
            fontWeight: '500',
            cursor: 'pointer'
          }}
        >
          🚪 Logout
        </button>
      </div>

      <div style={{ padding: '20px', paddingBottom: '100px', background: 'white', minHeight: 'calc(100vh - 140px)' }}>
        {/* Stats Cards */}
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '15px', marginBottom: '25px' }}>
          <div style={{
            background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
            color: 'white',
            padding: '20px',
            borderRadius: '20px',
            textAlign: 'center',
            boxShadow: '0 8px 25px rgba(102, 126, 234, 0.3)'
          }}>
            <div style={{ fontSize: '32px', fontWeight: 'bold', marginBottom: '5px' }}>{stats.totalUsers}</div>
            <div style={{ fontSize: '14px', opacity: '0.9' }}>👥 Total Users</div>
          </div>
          <div style={{
            background: 'linear-gradient(135deg, #ff6b6b 0%, #ee5a24 100%)',
            color: 'white',
            padding: '20px',
            borderRadius: '20px',
            textAlign: 'center',
            boxShadow: '0 8px 25px rgba(255, 107, 107, 0.3)'
          }}>
            <div style={{ fontSize: '32px', fontWeight: 'bold', marginBottom: '5px' }}>{stats.activeAlerts}</div>
            <div style={{ fontSize: '14px', opacity: '0.9' }}>⚠️ Active Alerts</div>
          </div>
          <div style={{
            background: 'linear-gradient(135deg, #4ecdc4 0%, #44a08d 100%)',
            color: 'white',
            padding: '20px',
            borderRadius: '20px',
            textAlign: 'center',
            boxShadow: '0 8px 25px rgba(78, 205, 196, 0.3)'
          }}>
            <div style={{ fontSize: '32px', fontWeight: 'bold', marginBottom: '5px' }}>{stats.resolvedAlerts}</div>
            <div style={{ fontSize: '14px', opacity: '0.9' }}>✅ Resolved</div>
          </div>
          <div style={{
            background: 'linear-gradient(135deg, #feca57 0%, #ff9ff3 100%)',
            color: 'white',
            padding: '20px',
            borderRadius: '20px',
            textAlign: 'center',
            boxShadow: '0 8px 25px rgba(254, 202, 87, 0.3)'
          }}>
            <div style={{ fontSize: '32px', fontWeight: 'bold', marginBottom: '5px' }}>{stats.onlineUsers}</div>
            <div style={{ fontSize: '14px', opacity: '0.9' }}>🟢 Online</div>
          </div>
        </div>

        {/* Recent Alerts */}
        <div style={{
          background: 'white',
          borderRadius: '20px',
          marginBottom: '25px',
          boxShadow: '0 8px 25px rgba(0,0,0,0.08)'
        }}>
          <div style={{
            padding: '20px 20px 15px 20px',
            borderBottom: '1px solid #f0f0f0',
            display: 'flex',
            alignItems: 'center',
            gap: '10px'
          }}>
            <span style={{ fontSize: '20px' }}>⚠️</span>
            <h3 style={{ margin: '0', fontSize: '18px', fontWeight: '600', color: '#333' }}>Emergency Alerts</h3>
          </div>
          <div style={{ padding: '15px' }}>
            {alerts.length === 0 ? (
              <div style={{ textAlign: 'center', padding: '20px', color: '#666' }}>
                <div style={{ fontSize: '40px', marginBottom: '10px' }}>🙏</div>
                <p>No emergency alerts</p>
              </div>
            ) : (
              alerts.map((alert) => (
                <div key={alert._id} style={{
                  background: '#f8f9fa',
                  borderRadius: '15px',
                  padding: '15px',
                  marginBottom: '10px',
                  border: alert.status === 'active' ? '2px solid #ff3b30' : '1px solid #e0e0e0'
                }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '10px' }}>
                    <div>
                      <div style={{ fontWeight: '600', fontSize: '16px', color: '#333' }}>
                        {alert.user?.fullName || 'Unknown User'}
                      </div>
                      <div style={{ fontSize: '12px', color: '#666', marginTop: '2px' }}>
                        {new Date(alert.createdAt).toLocaleString()}
                      </div>
                    </div>
                    <div style={{
                      background: alert.type === 'SOS' ? '#ff3b30' : '#ff9500',
                      color: 'white',
                      padding: '4px 12px',
                      borderRadius: '12px',
                      fontSize: '12px',
                      fontWeight: '500'
                    }}>
                      {alert.type}
                    </div>
                  </div>
                  <div style={{ fontSize: '14px', color: '#666', marginBottom: '10px' }}>
                    📍 {alert.location?.address || 'Location unknown'}
                  </div>
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <div style={{
                      background: alert.status === 'active' ? '#ff3b30' : '#34c759',
                      color: 'white',
                      padding: '4px 12px',
                      borderRadius: '12px',
                      fontSize: '12px',
                      fontWeight: '500'
                    }}>
                      {alert.status === 'active' ? '🔴 Active' : '✅ Resolved'}
                    </div>
                    {alert.status === 'active' && (
                      <button
                        onClick={() => resolveAlert(alert._id)}
                        style={{
                          background: '#34c759',
                          color: 'white',
                          border: 'none',
                          borderRadius: '12px',
                          padding: '8px 16px',
                          fontSize: '12px',
                          fontWeight: '500',
                          cursor: 'pointer'
                        }}
                      >
                        ✅ Resolve
                      </button>
                    )}
                  </div>
                </div>
              ))
            )}
          </div>
        </div>

        {/* Users List */}
        <div style={{
          background: 'white',
          borderRadius: '20px',
          boxShadow: '0 8px 25px rgba(0,0,0,0.08)'
        }}>
          <div style={{
            padding: '20px 20px 15px 20px',
            borderBottom: '1px solid #f0f0f0',
            display: 'flex',
            alignItems: 'center',
            gap: '10px'
          }}>
            <span style={{ fontSize: '20px' }}>👥</span>
            <h3 style={{ margin: '0', fontSize: '18px', fontWeight: '600', color: '#333' }}>Registered Users</h3>
          </div>
          <div style={{ padding: '15px' }}>
            {users.length === 0 ? (
              <div style={{ textAlign: 'center', padding: '20px', color: '#666' }}>
                <div style={{ fontSize: '40px', marginBottom: '10px' }}>👤</div>
                <p>No users found</p>
              </div>
            ) : (
              users.map((user) => (
                <div key={user._id} style={{
                  background: '#f8f9fa',
                  borderRadius: '15px',
                  padding: '15px',
                  marginBottom: '10px',
                  border: '1px solid #e0e0e0'
                }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '8px' }}>
                    <div>
                      <div style={{ fontWeight: '600', fontSize: '16px', color: '#333' }}>
                        {user.fullName}
                      </div>
                      <div style={{ fontSize: '14px', color: '#666', marginTop: '2px' }}>
                        📧 {user.email}
                      </div>
                      <div style={{ fontSize: '14px', color: '#666', marginTop: '2px' }}>
                        📱 {user.phone}
                      </div>
                    </div>
                    <div style={{
                      background: user.isActive ? '#34c759' : '#8e8e93',
                      color: 'white',
                      padding: '4px 12px',
                      borderRadius: '12px',
                      fontSize: '12px',
                      fontWeight: '500'
                    }}>
                      {user.isActive ? '🟢 Active' : '⚫ Inactive'}
                    </div>
                  </div>
                  <div style={{ fontSize: '12px', color: '#999' }}>
                    Last login: {new Date(user.lastLogin).toLocaleDateString()}
                  </div>
                </div>
              ))
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default AdminDashboard;
